// Queue class implementation
class Queue {
  constructor() {
    this.items = [];
  }
  
  enqueue(x) {
    this.items.push(x);
  }
  
  dequeue() {
    if (this.isEmpty()) {
      throw new Error("Cannot dequeue from an empty queue");
    }
    return this.items.shift();
  }
  
  size() {
    return this.items.length;
  }
  
  isEmpty() {
    return this.items.length === 0;
  }
  
  peek() {
    if (this.isEmpty()) {
      throw new Error("Cannot peek at an empty queue");
    }
    return this.items[0];
  }
}

